; =============== S U B R O U T I N E =======================================


Do_ControllerPal:
		stopZ80
		bsr.w	Poll_Controllers
		tst.b	(Water_full_screen_flag).w
		bne.s	+
		dma68kToVDP Normal_palette,0,Normal_palette_end-Normal_palette,CRAM
		bra.s	++

+
		dma68kToVDP Water_palette,0,Water_palette_end-Water_palette,CRAM

+
		dma68kToVDP Sprite_table,$F800,Sprite_table_end-Sprite_table,VRAM
		dma68kToVDP H_scroll_buffer,$F000,H_scroll_buffer_end-H_scroll_buffer,VRAM
		bsr.w	Process_DMA_Queue
		startZ80
		rts
; End of function Do_ControllerPal

		include	"Code/Horizontal Interrupts.asm"

; =============== S U B R O U T I N E =======================================


Init_Controllers:
		stopZ80
		moveq	#$40,d0
		move.b	d0,(HW_Port_1_Control).l
		move.b	d0,(HW_Port_2_Control).l
		move.b	d0,(HW_Expansion_Control).l
		startZ80
		rts
; End of function Init_Controllers


; =============== S U B R O U T I N E =======================================


Poll_Controllers:
		lea	(Ctrl_1).w,a0
		lea	(HW_Port_1_Data).l,a1
		bsr.s	Poll_Controller	; poll first controller
		addq.w	#2,a1	; poll second controller
; End of function Poll_Controllers


; =============== S U B R O U T I N E =======================================


Poll_Controller:
		move.b	#0,(a1)			; Poll controller data port
		nop
		nop
		move.b	(a1),d0			; Get controller port data (start/A)
		lsl.b	#2,d0
		andi.b	#$C0,d0
		move.b	#$40,(a1)		; Poll controller data port again
		nop
		nop
		move.b	(a1),d1			; Get controller port data (B/C/Dpad)
		andi.b	#$3F,d1
		or.b	d1,d0			; Fuse together into one controller bit array
		not.b	d0
		move.b	(a0),d1			; Get press button data
		eor.b	d0,d1			; Toggle off buttons that are being held
		move.b	d0,(a0)+		; Put raw controller input (for held buttons) in F604/F606
		and.b	d0,d1
		move.b	d1,(a0)+		; Put pressed controller input in F605/F607
		rts
; End of function Poll_Controller


; =============== S U B R O U T I N E =======================================


Init_VDP:
		lea	(VDP_control_port).l,a0
		lea	(VDP_data_port).l,a1
		lea	(VDP_register_values).l,a2
		moveq	#19-1,d7

.setRegisters:
		move.w	(a2)+,(a0)
		dbf	d7,.setRegisters
		move.w	(VDP_register_values+2).l,d0	; get command for register #1
		move.w	d0,(VDP_reg_1_command).w	; and store it in RAM (for easy display blanking/enabling)
		move.w	#$8A00+224-1,(H_int_counter_command).w
		moveq	#0,d0
		move.l	#vdpComm($0000,VSRAM,WRITE),(VDP_control_port).l
		move.w	d0,(a1)
		move.w	d0,(a1)
		move.l	#vdpComm($0000,CRAM,WRITE),(VDP_control_port).l
		move.w	#bytesToWcnt($80),d7

.clearCRAM:
		move.w	d0,(a1)
		dbf	d7,.clearCRAM
		clr.l	(V_scroll_value).w
		clr.l	(_unkF61A).w
		move.l	d1,-(sp)
		dmaFillVRAM 0,$0000,$10000	; clear entire VRAM
		move.l	(sp)+,d1
		rts
; End of function Init_VDP

; ---------------------------------------------------------------------------
VDP_register_values:
		dc.w $8004	; H-int disabled
		dc.w $8134	; V-int enabled, display blanked, DMA enabled, 224 line display
		dc.w $8230	; Scroll A PNT base $C000
		dc.w $8320	; Window PNT base $8000
		dc.w $8407	; Scroll B PNT base $E000
		dc.w $857C	; Sprite attribute table base $F800
		dc.w $8600
		dc.w $8700	; Backdrop color is color 0 of the first palette line
		dc.w $8800
		dc.w $8900
		dc.w $8A00
		dc.w $8B00	; Full-screen horizontal and vertical scrolling
		dc.w $8C81	; 40 cell wide display, no interlace
		dc.w $8D3C	; Horizontal scroll table base $F000
		dc.w $8E00
		dc.w $8F02	; Auto-increment is 2
		dc.w $9001	; Scroll planes are 64x32 cells
		dc.w $9100
		dc.w $9200	; Window disabled

; =============== S U B R O U T I N E =======================================


Clear_DisplayData:
		stopZ80
		dmaFillVRAM 0,$0000,$40

		tst.w	(Competition_mode).w
		beq.s	Clear_DisplayData_No2P
		dmaFillVRAM 0,$8000,$4000
		bra.s	Clear_DisplayData_Cont
; ---------------------------------------------------------------------------

Clear_DisplayData_No2P:
		dmaFillVRAM 0,$C000,$1000	; clear plane A PNT
		dmaFillVRAM 0,$E000,$1000	; clear plane B PNT

Clear_DisplayData_Cont:
		clr.l	(V_scroll_value).w
		clr.l	(_unkF61A).w
	if FixBugs
		clearRAM Sprite_table,(Sprite_table_end-Sprite_table)
		clearRAM H_scroll_buffer,(Collision_response_list_end-H_scroll_buffer)
	else
		; Bug: this should be (Sprite_table_End-Sprite_table)
		clearRAM Sprite_table,(Sprite_table_end-Sprite_table)+4
		; Bug: this should be (Collision_response_list_End-H_scroll_buffer)
		clearRAM H_scroll_buffer,(Collision_response_list_end-H_scroll_buffer)+4
	endif

		startZ80
		rts
; End of function Clear_DisplayData


; =============== S U B R O U T I N E =======================================


SndDrvInit:
		nop
		move.w	#$100,(Z80_bus_request).l
		move.w	#$100,(Z80_reset).l	; release Z80 reset

		; Load SMPS sound driver
		lea	(Z80_SoundDriver).l,a0
		lea	(Z80_RAM).l,a1
		bsr.w	Kos_Decomp
		; Load sound driver data (PSG envelopes, music/sound pointers, FM voice bank)
		lea	(Z80_SoundDriverData).l,a0
		lea	(Z80_RAM+z80_SoundDriverPointers).l,a1
		bsr.w	Kos_Decomp
		; Load default variables
		lea	(Z80_DefaultVariables).l,a0
		lea	(Z80_RAM+zDataStart).l,a1
		move.w	#Z80_DefaultVariables_end-Z80_DefaultVariables-1,d0

-
		move.b	(a0)+,(a1)+
		dbf	d0,-
		; Detect PAL region consoles
		btst	#6,(Graphics_flags).w
		beq.s	+
		move.b	#1,(Z80_RAM+zPalFlag).l

+
		move.w	#0,(Z80_reset).l	; reset Z80
		nop
		nop
		nop
		nop
		move.w	#$100,(Z80_reset).l	; release reset
		startZ80
		rts
; End of function SndDrvInit

; ---------------------------------------------------------------------------
; Default Z80 variables. These are actually set to more meaningful values
; in other SMPS Z80 drivers.
; ---------------------------------------------------------------------------
Z80_DefaultVariables:
		dc.b 0	; Unused 1
		dc.b 0	; Unused 2
		dc.b 0	; zPalFlag
		dc.b 0	; Unused 3
		dc.b 0	; zPalDblUpdCounter
		dc.b 0	; zSoundQueue0
		dc.b 0	; zSoundQueue1
		dc.b 0	; zSoundQueue2
		dc.b 0	; zTempoSpeedup
		dc.b 0	; zNextSound
		dc.b 0	; zMusicNumber
		dc.b 0	; zSFXNumber0
		dc.b 0	; zSFXNumber1
		dc.b 0	; zFadeOutTimeout
		dc.b 0	; zFadeDelay
		dc.b 0	; zFadeDelayTimeout
Z80_DefaultVariables_end:

; ---------------------------------------------------------------------------
; Always replaces an index previous passed to this function
; ---------------------------------------------------------------------------

; =============== S U B R O U T I N E =======================================


Play_Music:
		stopZ80
		move.b	d0,(Z80_RAM+zMusicNumber).l
		startZ80
		rts
; End of function Play_Music

; ---------------------------------------------------------------------------
; plays a sound if the source object is on-screen
; unused/dead code, left over from Sonic 2

Play_SFX_Local:
		tst.b	render_flags(a0)
		bpl.s	Play_SFX_Done

; ---------------------------------------------------------------------------
; Can handle up to two different indexes in one frame
; ---------------------------------------------------------------------------

; =============== S U B R O U T I N E =======================================


Play_SFX:
		stopZ80
		cmp.b	(Z80_RAM+zSFXNumber0).l,d0
		beq.s	++
		tst.b	(Z80_RAM+zSFXNumber0).l
		bne.s	+
		move.b	d0,(Z80_RAM+zSFXNumber0).l
		startZ80
		rts

+
		move.b	d0,(Z80_RAM+zSFXNumber1).l

+
		startZ80

Play_SFX_Done:
		rts
; End of function Play_SFX


; =============== S U B R O U T I N E =======================================


Change_Music_Tempo:
		stopZ80
		move.b	d0,(Z80_RAM+zTempoSpeedup).l
		startZ80
		rts
; End of function Change_Music_Tempo


; =============== S U B R O U T I N E =======================================


Pause_Game:
		nop
		tst.w	(Ending_running_flag).w
		beq.s	Pause_Main
		rts
; ---------------------------------------------------------------------------

Pause_Main:
		tst.b	(Life_count).w
		beq.w	Pause_Unpause
		tst.w	(Game_paused).w
		bne.s	+
		move.b	(Ctrl_1_pressed).w,d0
		andi.b	#button_start_mask,d0	; is Start pressed?
		beq.w	Pause_NoPause	; if not, branch

+
		move.w	#1,(Game_paused).w
		stopZ80
		move.b	#1,(Z80_RAM+zPauseFlag).l	; Pause the music
		startZ80

Pause_Loop:
		move.b	#VInt_ID_10,(V_int_routine).w
		bsr.w	Wait_VSync
		tst.b	(Slow_motion_flag).w
		beq.s	Pause_NoSlowMo
		btst	#button_A,(Ctrl_1_pressed).w
		beq.s	Pause_ChkFrameAdvance	; branch if A isn't pressed
		move.b	#GameMode_TitleScreen,(Game_mode).w	; set to title screen
		nop
		bra.s	Pause_ResumeMusic
; ---------------------------------------------------------------------------

Pause_ChkFrameAdvance:
		btst	#button_B,(Ctrl_1_held).w
		bne.s	Pause_FrameAdvance	; branch if B is held
		btst	#button_C,(Ctrl_1_pressed).w
		bne.s	Pause_FrameAdvance	; branch if C is pressed

Pause_NoSlowMo:
		cmpi.b	#$E,(Current_zone).w
		blo.s	Pause_ChkStart	; if the zone is below ALZ
		cmpi.b	#$12,(Current_zone).w
		bhi.s	Pause_ChkStart	; if the zone is above EMZ
		tst.b	(Competition_type).w
		bpl.s	Pause_ChkStart
		btst	#button_B,(Ctrl_1_pressed).w
		beq.s	Pause_ChkStart
		move.b	#GameMode_CompetitionLevelSelect+$80,(Game_mode).w	; If in time attack mode, go back to 2P menu if B is pressed
		bra.s	Pause_ResumeMusic
; ---------------------------------------------------------------------------

Pause_ChkStart:
		move.b	(Ctrl_1_pressed).w,d0
		andi.b	#button_start_mask,d0
		beq.s	Pause_Loop

Pause_ResumeMusic:
		stopZ80
		move.b	#$80,(Z80_RAM+zPauseFlag).l	; Unpause music
		startZ80

Pause_Unpause:
		move.w	#0,(Game_paused).w

Pause_NoPause:
		rts
; ---------------------------------------------------------------------------

Pause_FrameAdvance:
		move.w	#1,(Game_paused).w
		stopZ80
		move.b	#$80,(Z80_RAM+zPauseFlag).l	; Unpause music
		startZ80
		rts	; advance by a single frame
; End of function Pause_Game

; ---------------------------------------------------------------------------
; Copies a plane map to a plane PNT
; Inputs:
; a1 = map address
; d0 = VDP command to write to the PNT
; d1 = number of cells in a row - 1
; d2 = number of cell rows - 1
; ---------------------------------------------------------------------------

; =============== S U B R O U T I N E =======================================


Plane_Map_To_VRAM:
		lea	(VDP_data_port).l,a6
		move.l	#$80<<16,d4	; row increment value

-
		move.l	d0,VDP_control_port-VDP_data_port(a6)
		move.w	d1,d3

-
		move.w	(a1)+,(a6)
		dbf	d3,-	; copy one row
		add.l	d4,d0	; move onto next row
		dbf	d2,--	; and copy it
		rts
; End of function Plane_Map_To_VRAM

; ---------------------------------------------------------------------------
; Copies a plane map to a plane PNT, used for a 128-cell wide plane
; Inputs:
; a1 = map address
; d0 = VDP command to write to the PNT
; d1 = number of cells in a row - 1
; d2 = number of cell rows - 1
; ---------------------------------------------------------------------------

; =============== S U B R O U T I N E =======================================


Plane_Map_To_VRAM_2:
		lea	(VDP_data_port).l,a6
		move.l	#$100<<16,d4	; row increment value

-
		move.l	d0,VDP_control_port-VDP_data_port(a6)
		move.w	d1,d3

-
		move.w	(a1)+,(a6)
		dbf	d3,-	; copy one row
		add.l	d4,d0	; move onto next row
		dbf	d2,--	; and copy it
		rts
; End of function Plane_Map_To_VRAM_2

; ---------------------------------------------------------------------------
; Adds art to the DMA queue
; Inputs:
; d1 = source address
; d2 = destination VRAM address
; d3 = number of words to transfer
; ---------------------------------------------------------------------------

; =============== S U B R O U T I N E =======================================


Add_To_DMA_Queue:
	if Sonic3_Complete
		; Detect if transfer crosses 128KB boundary
		lsr.l	#1,d1
		move.w	d3,d0
		neg.w	d0
		sub.w	d1,d0
		bcc.s	.transfer
		; Do first transfer
		movem.l	d1-d3,-(sp)
		add.w	d0,d3		; d3 = words remaining in 128KB "bank"
		bsr.s	.transfer
		movem.l	(sp)+,d1-d3
		; Get second transfer's source, destination, and length
		moveq	#0,d0
		sub.w	d1,d0
		sub.w	d0,d3
		add.l	d0,d1
		add.w	d0,d2
		add.w	d0,d2
		; Do second transfer
	.transfer:
	endif

		movea.l	(DMA_queue_slot).w,a1
		cmpa.w	#DMA_queue_slot,a1	; is the queue full?
		beq.s	Add_To_DMA_Queue_Done	; if it is, return

		move.w	#$9300,d0
		move.b	d3,d0
		move.w	d0,(a1)+	; command to specify transfer length in words & $00FF

		move.w	#$9400,d0
		lsr.w	#8,d3
		move.b	d3,d0
		move.w	d0,(a1)+	; command to specify transfer length in words & $FF00

		move.w	#$9500,d0
	if Sonic3_Complete=0
		lsr.l	#1,d1
	endif
		move.b	d1,d0
		move.w	d0,(a1)+	; command to specify transfer source & $0001FE

		move.w	#$9600,d0
		lsr.l	#8,d1
		move.b	d1,d0
		move.w	d0,(a1)+	; command to specify transfer source & $01FE00

		move.w	#$9700,d0
		lsr.l	#8,d1
		andi.b	#$7F,d1		; this instruction safely allows source to be in RAM; S2's lacks this
		move.b	d1,d0
		move.w	d0,(a1)+	; command to specify transfer source & $FE0000

		andi.l	#$FFFF,d2
		lsl.l	#2,d2
		lsr.w	#2,d2
		swap	d2
		ori.l	#vdpComm($0000,VRAM,DMA),d2
		move.l	d2,(a1)+	; command to specify transfer destination and begin DMA

		move.l	a1,(DMA_queue_slot).w	; set new free slot address
		cmpa.w	#DMA_queue_slot,a1	; has the end of the queue been reached?
		beq.s	Add_To_DMA_Queue_Done	; if it has, branch
		move.w	#0,(a1)	; place stop token at the end of the queue

Add_To_DMA_Queue_Done:
		rts
; End of function Add_To_DMA_Queue


; =============== S U B R O U T I N E =======================================


Process_DMA_Queue:
		lea	(VDP_control_port).l,a5
		lea	(DMA_queue).w,a1

.loop:
		move.w	(a1)+,d0	; has a stop token been encountered?
		beq.s	.stop	; if it has, branch
		move.w	d0,(a5)
		move.w	(a1)+,(a5)
		move.w	(a1)+,(a5)
		move.w	(a1)+,(a5)
		move.w	(a1)+,(a5)
		move.w	(a1)+,(a5)
		move.w	(a1)+,(a5)
		cmpa.w	#DMA_queue_slot,a1	; has the end of the queue been reached?
		bne.s	.loop	; if not, loop

.stop:
		move.w	#0,(DMA_queue).w
		move.l	#DMA_queue,(DMA_queue_slot).w
		rts
; End of function Process_DMA_Queue

		include	"Code/Decompression/Nemesis Decompression.asm"
		include	"Code/PLC Queue System.asm"
		include	"Code/Decompression/Enigma Decompression.asm"
		include	"Code/Decompression/Kosinski Decompression.asm"
		include	"Code/Decompression/Kosinski Moduled Decompression.asm"

; ---------------------------------------------------------------------------
; Called at the end of each frame to perform vertical synchronization
; ---------------------------------------------------------------------------

; =============== S U B R O U T I N E =======================================


Wait_VSync:
		move	#$2300,sr

.loop:
		tst.b	(V_int_routine).w
		bne.s	.loop	; wait until V-int's run
		rts
; End of function Wait_VSync

