		dc.w  $8000,     0,     0,     0,  $300
		dc.w  $8000,     0,     0,     0,  $300
		dc.w  $8000,     0,     0,     0,  $300
		dc.w  $8000,     0,     0,     0,  $300
		dc.w  $8000,     0,     0,     0,  $300
