AirCountdown_Countdown:
		movea.l	$40(a0),a2	; a2=character
		tst.w	$30(a0)
		bne.w	loc_1857C
		cmpi.b	#6,routine(a2)
		bhs.w	locret_18680
		btst	#Status_BublShield,status_secondary(a2)
		bne.w	locret_18680
		tst.b	(Super_Sonic_Knux_flag).w
		bmi.w	locret_18680
		btst	#Status_Underwater,status(a2)
		beq.w	locret_18680
		subq.w	#1,$3C(a0)
		bpl.w	loc_18594
		move.w	#60-1,$3C(a0)
		move.w	#1,$3A(a0)
		jsr	(Random_Number).l
		andi.w	#1,d0
		move.b	d0,$38(a0)
		moveq	#0,d0
		move.b	air_left(a2),d0	; check air remaining
		cmpi.w	#25,d0
		beq.s	AirCountdown_WarnSound	; play ding sound if air is 25
		cmpi.w	#20,d0
		beq.s	AirCountdown_WarnSound	; play ding sound if air is 20
		cmpi.w	#15,d0
		beq.s	AirCountdown_WarnSound	; play ding sound if air is 15
		cmpi.w	#12,d0
		bhi.s	AirCountdown_ReduceAir
		bne.s	loc_184E8
		tst.b	parent+1(a0)
		bne.s	loc_184E8
		moveq	#signextendB(mus_Drowning),d0
		jsr	(Play_Music).l

loc_184E8:
		subq.b	#1,$36(a0)
		bpl.s	AirCountdown_ReduceAir
		move.b	$37(a0),$36(a0)
		bset	#7,$3A(a0)
		bra.s	AirCountdown_ReduceAir
; ---------------------------------------------------------------------------

AirCountdown_WarnSound:
		tst.b	parent+1(a0)
		bne.s	AirCountdown_ReduceAir
		moveq	#signextendB(sfx_AirDing),d0
		jsr	(Play_SFX).l

AirCountdown_ReduceAir:
		subq.b	#1,air_left(a2)
		bcc.w	loc_18592
		move.b	#$81,object_control(a2)
		move.w	#sfx_Drown,d0
		jsr	(Play_SFX).l
		move.b	#$A,$38(a0)
		move.w	#1,$3A(a0)
		move.w	#$78,$30(a0)
		movea.l	a2,a1
		bsr.w	Player_ResetAirTimer
		move.l	a0,-(sp)
		movea.l	a2,a0
		bsr.w	Player_TouchFloor
		move.b	#$17,anim(a0)
		bset	#Status_InAir,status(a0)
		bset	#7,art_tile(a0)
		move.w	#0,y_vel(a0)
		move.w	#0,x_vel(a0)
		move.w	#0,ground_vel(a0)
		move.b	#$C,routine(a0)
		movea.l	(sp)+,a0
		cmpa.w	#Player_1,a2
		bne.s	locret_1857A
		move.b	#1,(Deform_lock).w

locret_1857A:
		rts
; ---------------------------------------------------------------------------

loc_1857C:
		move.b	#$17,anim(a2)
		subq.w	#1,$30(a0)
