AirCountdown_MakeItem:
		jsr	(Random_Number).l
		andi.w	#$F,d0
		addq.w	#8,d0
		move.w	d0,$3E(a0)
		jsr	(AllocateObject).l
		bne.w	locret_18680
		move.l	(a0),(a1)		; load Obj_Air_Countdown
		move.w	x_pos(a2),x_pos(a1)	; match its X position to Sonic
		moveq	#6,d0
		btst	#Status_Facing,status(a2)
		beq.s	loc_185D8
		neg.w	d0
		move.b	#$40,angle(a1)

loc_185D8:
		add.w	d0,x_pos(a1)
		move.w	y_pos(a2),y_pos(a1)
		move.l	$40(a0),$40(a1)
		move.b	#6,subtype(a1)
		tst.w	$30(a0)
		beq.w	loc_1862A
		andi.w	#7,$3E(a0)
		addi.w	#0,$3E(a0)
		move.w	y_pos(a2),d0
		subi.w	#$C,d0
		move.w	d0,y_pos(a1)
		jsr	(Random_Number).l
		move.b	d0,angle(a1)
		move.w	(Level_frame_counter).w,d0
		andi.b	#3,d0
		bne.s	loc_18676
		move.b	#$E,subtype(a1)
		bra.s	loc_18676
; ---------------------------------------------------------------------------
; has something to do with making bubbles come out less regularly
; when Sonic is almost drowning
loc_1862A:
		btst	#7,$3A(a0)
		beq.s	loc_18676
		moveq	#0,d2
		move.b	air_left(a2),d2
		cmpi.b	#12,d2
		bhs.s	loc_18676
		lsr.w	#1,d2
		jsr	(Random_Number).l
		andi.w	#3,d0
		bne.s	loc_1865E
		bset	#6,$3A(a0)
		bne.s	loc_18676
		move.b	d2,subtype(a1)
		move.w	#$1C,$3C(a1)

loc_1865E:
		tst.b	$38(a0)
		bne.s	loc_18676
		bset	#6,$3A(a0)
		bne.s	loc_18676
		move.b	d2,subtype(a1)
		move.w	#$1C,$3C(a1)

loc_18676:
		subq.b	#1,$38(a0)
		bpl.s	locret_18680
		clr.w	$3A(a0)

locret_18680:
		rts

