Obj_SuperTailsBirds_FindTarget:
		moveq	#0,d1
		lea	(Collision_response_list).w,a4
		move.w	(a4)+,d6
		beq.s	.return
		moveq	#0,d0
		addq.b	#2,(_unkF66C).w
		cmp.b	(_unkF66C).w,d6
		bhi.s	.noreset
		move.b	#0,(_unkF66C).w

	.noreset:
		move.b	(_unkF66C).w,d0
		sub.w	d0,d6
		lea	(a4,d0.w),a4

	.loop:
		movea.w	(a4)+,a1
		move.b	collision_flags(a1),d0
		beq.s	.ignore_object
		bsr.s	.check_if_object_valid

	.ignore_object:
		subq.w	#2,d6
		bne.s	.loop

	.return:
		rts
; End of function Obj_SuperTailsBirds_FindTarget


; =============== S U B R O U T I N E =======================================


	.check_if_object_valid:
		tst.b	render_flags(a1)
		bpl.s	.invalid
		tst.b	$2D(a1)
		bne.s	.invalid
		andi.b	#$C0,d0
		beq.s	.valid
		cmpi.b	#$C0,d0
		beq.s	.valid

	.invalid:
		rts
; ---------------------------------------------------------------------------

	.valid:
		move.b	#-1,$2D(a1)
		move.w	a1,superTailsBirds_target_address(a0)
		move.b	#1,superTailsBirds_target_found(a0)
		moveq	#1,d1
		moveq	#2,d6
		rts
