loc_51436:
		move.l	$64(a1),d3
		add.l	d3,(a5)+		; Add velocity to actual VScroll
		move.w	-4(a5),d3
		cmpi.w	#$2E0,d3
		blo.s	loc_5144C
		move.w	#$2E0,d3		; $2E0 is the maximum scroll
