		move.w	d0,(Camera_Y_pos_BG_copy).w
		move.w	(Camera_X_pos_copy).w,d0
		move.w	(Screen_shake_offset).w,d3
		sub.w	d3,d0
		swap	d0
		clr.w	d0
		asr.l	#5,d0
		move.l	d0,d1
		swap	d0
		add.w	d3,d0
		swap	d0
		lea	(HScroll_table).w,a1
		moveq	#0,d3
		moveq	#5-1,d2			; First five deformation speeds are constant
		bsr.s	sub_53996
		add.l	d1,d0
		move.l	d1,d2
		asr.l	#1,d2
		add.l	d2,d1
		move.l	$12(a1),d3
		addi.l	#$800,$12(a1)
		moveq	#9-1,d2			; Last 9 move slowly automatically
; End of function ICZ1_IntroDeform


; =============== S U B R O U T I N E =======================================


sub_53996:
		swap	d0
		move.w	d0,(a1)+
		swap	d0
		add.l	d1,d0
		add.l	d3,d1
		addi.l	#$800,d3
		dbf	d2,sub_53996
		rts
; End of function sub_53996


